import sys

def greet(name="World"):
    """Returns a greeting string without a trailing newline."""
    return f"Hello, {name}"

def main():
    """Handles command-line arguments for greeting."""
    if len(sys.argv) > 1:
        name = sys.argv[1]
        print(f"Hello, {name}!")
    else:
        print("Hello, World!")

if __name__ == "__main__":
    main()
